import { BANK_ACTIONS } from './actions'

const reducer = (state = BANK_ACTIONS, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case BANK_ACTIONS.GET_BANK_ACCOUNT_LIST:
      return {
        ...state,
        getBankAccountListData: {
          meta_data:
            payload?.getBankAccountListData?.meta_data ||
            state?.getBankAccountListData?.meta_data,
          data: [
            ...(state.getBankAccountListData?.data || []),
            ...(payload.getBankAccountListData?.data || []),
          ],
        },
      }
    case BANK_ACTIONS.UPDATE_BANK_ACCOUNT:
      return {
        ...state,
        ...payload,
      }
    case BANK_ACTIONS.VERIFY_BANK_ACCOUNT:
      return {
        ...state,
        ...payload,
      }
    case BANK_ACTIONS.GET_BANK_ACCOUNT_DETAILS:
      return {
        ...state,
        ...payload,
      }
    case BANK_ACTIONS.SEND_OTP:
      return {
        ...state,
        ...payload,
      }
    case BANK_ACTIONS.RESET_POLICY_STATE:
    case BANK_ACTIONS.SET_POLICY_STATE:
      return {
        ...state,
        ...payload,
      }
    default:
      return {
        ...(state || {}),
      }
  }
}

export default reducer
