import { Container, CustomText, OtpInput, Button } from '../../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import { OtpInputWrapper } from './index.style'
import { PASAR_MITRA_STACKED } from '../../../../../../../../images'
import { LANG_STRINGS } from '../../../../../../../../lang'
import { React, useEffect, useState, useCallback } from 'react'
import { getFromLocalStorageData, removeFromLocalStorageData, setToLocalStorage } from '../../../../../../../../helpers/localstorage'
import { OTP_END_TIME, BANK_FORM_DATA } from '../../../../../constants'
import { useResendOtp } from '../../../../../state/MyProfile/hooks/useMyProfileContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'
import { useHistory } from 'react-router'
import isEmpty from 'lodash/isEmpty'
import { useVerifyBankAccounts } from '../../../state/hooks/useBankAccounts'

function OtpPageContainer () {
  const [otpError, setOtpError] = useState(false)
  const { initialMinute = 1, initialSeconds = 59 } = 60

  const getTimeRemaining = (otpEndTime) => {
    const total = otpEndTime - (new Date().getTime())
    const seconds = Math.floor((total / 1000) % 60)
    const minutes = Math.floor((total / 1000 / 60) % 60)
    return {
      total,
      minutes,
      seconds
    }
  }

  const getCurrentTime = () => {
    return new Date().getTime() + 2 * 60000
  }

  const updateEndTime = useCallback(() => {
    if (isEmpty(getFromLocalStorageData(OTP_END_TIME))) {
      setToLocalStorage(OTP_END_TIME, {
        otpEndTime: getCurrentTime()
      })
    }
  }, [])

  const isExceedTimeThreshold = () => {
    const localData = getFromLocalStorageData(OTP_END_TIME)
    return (new Date().getTime() > localData.otpEndTime)
  }

  useEffect(() => {
    updateEndTime()
  }, [updateEndTime])

  const otpEndTime = getFromLocalStorageData(OTP_END_TIME).otpEndTime

  const [minutes, setMinutes] = useState(
    otpEndTime ? isExceedTimeThreshold() ? 0 : getTimeRemaining(otpEndTime).minutes : initialMinute)
  const [seconds, setSeconds] = useState(
    otpEndTime ? isExceedTimeThreshold() ? 0 : getTimeRemaining(otpEndTime).seconds : initialSeconds)

  const [, verifyBankAccountsRequest] = useVerifyBankAccounts()
  const [resendOtpResponse, resendOtpRequest] = useResendOtp()
  const [{ verifyBankAccountStatus = '', resendOtpStatus = '', resendOtpErrorData }, dispatchError] = useErrorContextValue()
  const [{ RESEND_OTP_LOADER, VERIFY_BANK_ACCOUNT_LOADER }] = useLoaderContextValue()

  const history = useHistory()
  const { resetError } = useResetError()
  const [bankData, setBankData] = useState({ bank_id: '', operation_id: '' })

  useEffect(() => {
    if (bankData.bank_id === '') {
      const localData = getFromLocalStorageData(BANK_FORM_DATA)
      setBankData({
        bank_id: localData.bank_id,
        operation_id: localData.operation_id
      })
    }
  }, [bankData])

  useEffect(() => {
    const myInterval = setInterval(() => {
      if (seconds > 0) {
        setSeconds(seconds - 1)
      }
      if (seconds === 0) {
        if (minutes === 0) {
          clearInterval(myInterval)
        } else {
          setMinutes(minutes - 1)
          setSeconds(59)
        }
      }
    }, 1000)
    return () => {
      clearInterval(myInterval)
    }
  })

  const handleResendOtp = useCallback((isWhatsapp) => {
    const { bank_id: bankId, operation_id: operationId } = bankData
    const body = {
      bank_id: bankId,
      operation_id: operationId
    }
    if (isWhatsapp) {
      body.medium = 'whatsapp'
    }
    resendOtpRequest(body)
  }, [bankData, resendOtpRequest])

  useEffect(() => {
    if (resendOtpStatus === 'success') {
      setOtpError('')
      setToLocalStorage(OTP_END_TIME, {
        otpEndTime: getCurrentTime()
      })
      setSeconds(59)
      setMinutes(1)
      resetError(['resendOtpStatus'])
    } else if (resendOtpStatus) {
      if (resendOtpErrorData?.error_code === 'US105') {
        history.push('/my-profile')
        removeFromLocalStorageData(OTP_END_TIME)
        setOtpError(resendOtpStatus)
        resetError(['resendOtpStatus'])
        ShowSnackbar.error({
          visible: true,
          text: resendOtpStatus
        })
      } else {
        ShowSnackbar.error({
          visible: true,
          text: resendOtpStatus
        })
        setSeconds(59)
        setMinutes(1)
        setToLocalStorage(OTP_END_TIME, {
          otpEndTime: getCurrentTime()
        })
      }
      setOtpError(resendOtpStatus)
      resetError(['resendOtpStatus'])
    }
  }, [
    resendOtpResponse, resendOtpStatus, dispatchError,
    resetError, bankData, history, resendOtpErrorData?.error_code])

  const handleSubmit = (value) => {
    const body = {
      operation_id: bankData.operation_id,
      otp: value,
      bank_id: bankData.bank_id
    }
    verifyBankAccountsRequest(body)
  }

  useEffect(() => {
    if (verifyBankAccountStatus === 'success') {
      removeFromLocalStorageData(OTP_END_TIME)
      history.replace({ pathname: '/bank-account' })
      ShowSnackbar.success({
        visible: true,
        text: 'Rekening Bank berhasil disimpan.'
      })
    } else if (verifyBankAccountStatus) {
      ShowSnackbar.error({
        visible: true,
        text: verifyBankAccountStatus
      })
    }
    resetError(['verifyBankAccountStatus'])
  }, [history, dispatchError, verifyBankAccountStatus, resetError])

  return (
    <Container
      displayBackButton
      hideBottomTabs
      loader={RESEND_OTP_LOADER || VERIFY_BANK_ACCOUNT_LOADER}
    >
      <OtpInputWrapper>
        {<img className='logo-img' src={PASAR_MITRA_STACKED} alt='Mitra' />}
        <div className='otp-form'>
          <CustomText
            color={AgentColorPallette.regular}
            lineHeight={1.5}
            size='16px'
            weight={600}
            bottom='10px'
          >
            {LANG_STRINGS.otpTitleTextMessage}
          </CustomText>
          <OtpInput
            isNewDesign
            onSubmit={handleSubmit}
            disabled={minutes === 0 && seconds === 0}
            error={otpError}
          />
        </div>
        {
          seconds !== 0 || minutes !== 0 ? (
            <>
              <CustomText
                className='otp-not-received-text'
                color={AgentColorPallette.regular}
                size='14px'
                weight={700}
              >
                {LANG_STRINGS.otpNotRecievedMessage}
              </CustomText>
              <CustomText
                className='otp-not-received-text'
                size='13px'
                color={AgentColorPallette.regular}
              >
                {LANG_STRINGS.otpNotRecievedTimerMessage}
                <b>{minutes}:{seconds < 10 ? `0${seconds}` : seconds}</b>
              </CustomText>
            </>
          )
            : (
              <CustomText
                className='otp-not-received-text'
                color={AgentColorPallette.regular}
                size='14px'
                weight={700}
              >
                {LANG_STRINGS.otpNotRecievedMessage}
                <span className='button-helepr-text'> Kirim ulang menggunakan</span>
              </CustomText>
            )
        }
        {
          seconds === 0 && minutes === 0 &&
            <div className='button'>
              <Button
                className='resend-otp'
                onClick={() => handleResendOtp()}
                id='resend-otp'
                color={AgentColorPallette.white}
                backgroundColor={AgentColorPallette.regular}
              >
                <CustomText
                  className='button-text'
                  color={AgentColorPallette.white}
                  size='10px'
                  weight={700}
                >
                  SMS
                </CustomText>
              </Button>
              <Button
                className='resend-otp'
                id='resend-otp'
                backgroundColor={AgentColorPallette.regular}
                color={AgentColorPallette.white}
                onClick={() => handleResendOtp(true)}
              >
                <CustomText
                  className='button-text'
                  color={AgentColorPallette.white}
                  size='10px'
                  weight={700}
                >
                  WHATSAPP
                </CustomText>
              </Button>
            </div>
        }
      </OtpInputWrapper>
    </Container>
  )
}
export default OtpPageContainer
