import { createContext, useContext, useReducer } from 'react'

// this to create context
export const ProfileContext = createContext()

// Context Provider
export const ProfileContextProvider = ({ reducer, ...props }) => {
  return (
    <ProfileContext.Provider value={useReducer(reducer, {})}>
      {props.children}
    </ProfileContext.Provider>
  )
}

// use context value
export const useProfileContextValue = () => useContext(ProfileContext)
